export const envelope = [28, 38, 28];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 6;

  // Theme-derived palette
  const stonePrimary = api.theme.stone.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme.stone.accent || "minecraft:cobblestone";
  const stoneStairs = api.theme.stone.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme.stone.slab || "minecraft:stone_brick_slab";
  const scree = api.theme.ground.scree || api.theme.stone.accent || "minecraft:cobblestone";

  const woodPlanks = api.theme.wood.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood.log || "minecraft:spruce_log";
  const woodStairs = api.theme.wood.stairs || "minecraft:spruce_stairs";
  const woodFence = api.theme.wood.fence || "minecraft:spruce_fence";
  const woodTrapdoor = api.theme.wood.trapdoor || "minecraft:spruce_trapdoor";

  // 3D voxel staging buffer [x][y][z]
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => Array(D).fill(null))
  );

  const setCell = (x, y, z, block) => {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  };

  // -------------------------------------------------------------
  // Phase 1: Sculpt Natural Skull Rock Crag (Relative y0: 0..23)
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let y0 = 0; y0 <= 23; y0++) {
      for (let z = 0; z < D; z++) {
        const dx = x - 14;
        const dz = z - 14;

        // Cranium dome
        const cranium =
          (dx * dx) / (8.2 * 8.2) +
          ((y0 - 17.5) * (y0 - 17.5)) / (6.5 * 6.5) +
          (dz * dz) / (8.2 * 8.2);

        // Brow ridge protrusion
        const brow =
          (dx * dx) / (7.5 * 7.5) +
          ((y0 - 18.0) * (y0 - 18.0)) / (2.0 * 2.0) +
          ((z - 7.5) * (z - 7.5)) / (3.2 * 3.2);

        // Cheekbones / Upper Jaw
        const jawZ = z - 12;
        const jaw =
          (dx * dx) / (7.2 * 7.2) +
          ((y0 - 9.0) * (y0 - 9.0)) / (5.5 * 5.5) +
          (jawZ * jawZ) / (6.8 * 6.8);

        // Cliff base skirt
        let base = 999;
        if (y0 <= 7) {
          const baseR = 8.6 + (7 - y0) * 0.75;
          base = (dx * dx + dz * dz) / (baseR * baseR);
        }

        // Craggy coastal variation
        const noise =
          Math.sin(x * 0.65 + y0 * 0.5) * 0.22 +
          Math.cos(z * 0.6 + y0 * 0.45) * 0.22;

        const isSolid =
          cranium <= 1.0 + noise ||
          brow <= 0.9 + noise ||
          jaw <= 1.0 + noise ||
          base <= 1.0 + noise;

        if (isSolid) {
          const hash = Math.sin(x * 3.1 + y0 * 7.3 + z * 5.7) * 10000;
          const rnd = hash - Math.floor(hash);
          const block = rnd < 0.62 ? stonePrimary : (rnd < 0.84 ? stoneAccent : scree);
          setCell(x, seatY + y0, z, block);
        }
      }
    }
  }

  // -------------------------------------------------------------
  // Phase 2: Carve Facial Features & Interior Caverns
  // -------------------------------------------------------------

  // 1. Gaping Mouth / Sea Grotto Entrance
  for (let x = 0; x < W; x++) {
    for (let y0 = 0; y0 <= 10; y0++) {
      for (let z = 0; z < D; z++) {
        const dx = x - 14;
        // Mouth archway (North entrance)
        if (z <= 11) {
          if ((dx * dx) / (4.2 * 4.2) + ((y0 - 3.2) * (y0 - 3.2)) / (3.8 * 3.8) <= 1.0 && y0 >= 0) {
            setCell(x, seatY + y0, z, null);
          }
        }
        // Lower cavern chamber
        if (z >= 7 && z <= 22 && y0 >= 1 && y0 <= 9) {
          const dzCave = z - 14;
          if ((dx * dx) / (6.4 * 6.4) + ((y0 - 5.0) * (y0 - 5.0)) / (4.0 * 4.0) + (dzCave * dzCave) / (6.8 * 6.8) <= 1.0) {
            setCell(x, seatY + y0, z, null);
          }
        }
      }
    }
  }

  // Jagged Skull Teeth in Mouth Opening
  const upperTeethX = [11, 13, 15, 17];
  for (const tx of upperTeethX) {
    setCell(tx, seatY + 6, 6, stoneStairs + "[facing=south,half=top]");
    setCell(tx, seatY + 7, 6, stonePrimary);
  }
  const lowerTeethX = [12, 14, 16];
  for (const tx of lowerTeethX) {
    setCell(tx, seatY + 1, 6, stoneStairs + "[facing=south,half=bottom]");
    setCell(tx, seatY + 0, 6, stonePrimary);
  }

  // 2. Nasal Aperture (Inverted triangular cavity)
  for (let x = 12; x <= 16; x++) {
    for (let y0 = 10; y0 <= 13; y0++) {
      for (let z = 4; z <= 8; z++) {
        const dx = x - 14;
        const dy = y0 - 11.5;
        const dz = z - 6.0;
        const rw = 1.4 - (y0 - 10) * 0.25;
        if ((dx * dx) / (rw * rw) + (dy * dy) / (1.8 * 1.8) + (dz * dz) / (2.2 * 2.2) <= 1.0) {
          setCell(x, seatY + y0, z, null);
        }
      }
    }
  }

  // 3. Eye Sockets (Deep menacing voids facing North)
  const eyeSockets = [
    { cx: 9.2, cy0: 15.5, cz: 6.2 },  // Left Eye
    { cx: 18.8, cy0: 15.5, cz: 6.2 } // Right Eye
  ];
  for (const eye of eyeSockets) {
    for (let x = Math.floor(eye.cx - 4); x <= Math.ceil(eye.cx + 4); x++) {
      for (let y0 = Math.floor(eye.cy0 - 4); y0 <= Math.ceil(eye.cy0 + 4); y0++) {
        for (let z = 3; z <= 10; z++) {
          const dx = x - eye.cx;
          const dy = y0 - eye.cy0;
          const dz = z - eye.cz;
          if ((dx * dx) / (2.4 * 2.4) + (dy * dy) / (2.2 * 2.2) + (dz * dz) / (3.5 * 3.5) <= 1.0) {
            setCell(x, seatY + y0, z, null);
          }
        }
      }
    }
  }

  // 4. Upper Interior Gun Deck & Captain's Sanctum (Inside Cranium)
  for (let x = 7; x <= 21; x++) {
    for (let y0 = 13; y0 <= 21; y0++) {
      for (let z = 7; z <= 21; z++) {
        const dx = x - 14;
        const dy = y0 - 17.0;
        const dz = z - 14;
        if ((dx * dx) / (5.6 * 5.6) + (dy * dy) / (3.8 * 3.8) + (dz * dz) / (5.6 * 5.6) <= 1.0) {
          setCell(x, seatY + y0, z, null);
        }
      }
    }
  }

  // 5. Lateral Temporal Indentations
  for (let y0 = 13; y0 <= 18; y0++) {
    for (let z = 9; z <= 14; z++) {
      for (let x = 0; x <= 6; x++) {
        const dx = x - 5.5;
        const dy = y0 - 15.5;
        const dz = z - 11.5;
        if ((dx * dx) / (2.5 * 2.5) + (dy * dy) / (3.0 * 3.0) + (dz * dz) / (3.0 * 3.0) <= 1.0) {
          setCell(x, seatY + y0, z, null);
        }
      }
      for (let x = 22; x < W; x++) {
        const dx = x - 22.5;
        const dy = y0 - 15.5;
        const dz = z - 11.5;
        if ((dx * dx) / (2.5 * 2.5) + (dy * dy) / (3.0 * 3.0) + (dz * dz) / (3.0 * 3.0) <= 1.0) {
          setCell(x, seatY + y0, z, null);
        }
      }
    }
  }

  // -------------------------------------------------------------
  // Phase 3: Timber Fortifications, Gun Decks & Naval Cannons
  // -------------------------------------------------------------

  // Interior Gun Deck Flooring at y0 = 13
  for (let x = 8; x <= 20; x++) {
    for (let z = 7; z <= 20; z++) {
      const dx = x - 14;
      const dz = z - 14;
      if ((dx * dx) / (5.8 * 5.8) + (dz * dz) / (5.8 * 5.8) <= 1.0) {
        setCell(x, seatY + 13, z, woodPlanks);
      }
    }
  }

  // Lower Cave Floor at y0 = 0
  for (let x = 8; x <= 20; x++) {
    for (let z = 6; z <= 22; z++) {
      const dx = x - 14;
      const dz = z - 14;
      if ((dx * dx) / (6.8 * 6.8) + (dz * dz) / (7.8 * 7.8) <= 1.0) {
        setCell(x, seatY + 0, z, (x + z) % 2 === 0 ? stoneAccent : woodPlanks);
      }
    }
  }

  // Eye Socket Heavy Cannons (Trained Northward over the sea)
  const placeCannon = (gunX, gunY, gunZ) => {
    setCell(gunX, gunY, gunZ + 2, woodPlanks);
    setCell(gunX, gunY, gunZ + 1, "minecraft:polished_blackstone");
    setCell(gunX, gunY, gunZ, "minecraft:dispenser[facing=north]");
    setCell(gunX, gunY, gunZ - 1, "minecraft:iron_bars");
    setCell(gunX, gunY + 1, gunZ + 1, woodTrapdoor + "[facing=north,half=bottom]");
  };

  placeCannon(9, seatY + 14, 5);
  placeCannon(10, seatY + 14, 5);
  placeCannon(17, seatY + 14, 5);
  placeCannon(18, seatY + 14, 5);

  // Exterior Timber Balconies clinging to Temple Cliffs
  // West Balcony
  for (let z = 10; z <= 16; z++) {
    for (let x = 3; x <= 6; x++) {
      setCell(x, seatY + 13, z, woodPlanks);
    }
    setCell(3, seatY + 14, z, woodFence);
  }
  setCell(3, seatY + 14, 10, woodFence);
  setCell(3, seatY + 14, 16, woodFence);
  for (let z = 11; z <= 15; z += 3) {
    setCell(5, seatY + 12, z, woodLog + "[axis=y]");
    setCell(4, seatY + 12, z, woodStairs + "[facing=east,half=top]");
    setCell(5, seatY + 11, z, woodStairs + "[facing=east,half=bottom]");
  }

  // East Balcony
  for (let z = 10; z <= 16; z++) {
    for (let x = 21; x <= 24; x++) {
      setCell(x, seatY + 13, z, woodPlanks);
    }
    setCell(24, seatY + 14, z, woodFence);
  }
  setCell(24, seatY + 14, 10, woodFence);
  setCell(24, seatY + 14, 16, woodFence);
  for (let z = 11; z <= 15; z += 3) {
    setCell(22, seatY + 12, z, woodLog + "[axis=y]");
    setCell(23, seatY + 12, z, woodStairs + "[facing=west,half=top]");
    setCell(22, seatY + 11, z, woodStairs + "[facing=west,half=bottom]");
  }

  // -------------------------------------------------------------
  // Phase 4: Top Bastion Deck, Crow's Nest Mast & Black Pirate Flag
  // -------------------------------------------------------------

  // Top Bastion Deck at y0 = 23
  for (let x = 9; x <= 19; x++) {
    for (let z = 9; z <= 19; z++) {
      const dx = x - 14;
      const dz = z - 14;
      if (dx * dx + dz * dz <= 5.4 * 5.4) {
        setCell(x, seatY + 23, z, woodPlanks);
      }
    }
  }

  // Timber Rim & Battlements at y0 = 24
  for (let x = 8; x <= 20; x++) {
    for (let z = 8; z <= 20; z++) {
      const dx = x - 14;
      const dz = z - 14;
      const r2 = dx * dx + dz * dz;
      if (r2 >= 4.0 * 4.0 && r2 <= 5.8 * 5.8) {
        if (grid[x][seatY + 23][z] || grid[x][seatY + 22][z]) {
          if ((x + z) % 2 === 0) {
            setCell(x, seatY + 24, z, woodLog + "[axis=y]");
          } else {
            setCell(x, seatY + 24, z, woodFence);
          }
        }
      }
    }
  }

  // Top Bastion North Artillery Battery
  placeCannon(11, seatY + 24, 8);
  placeCannon(17, seatY + 24, 8);

  // Central Watch Mast (y0 = 24..31)
  for (let y0 = 24; y0 <= 31; y0++) {
    setCell(14, seatY + y0, 14, woodLog + "[axis=y]");
  }

  // Crow's Nest Platform at y0 = 28
  for (let x = 13; x <= 15; x++) {
    for (let z = 13; z <= 15; z++) {
      if (x !== 14 || z !== 14) {
        setCell(x, seatY + 28, z, woodPlanks);
        setCell(x, seatY + 29, z, woodFence);
      }
    }
  }
  setCell(13, seatY + 27, 14, woodStairs + "[facing=east,half=top]");
  setCell(15, seatY + 27, 14, woodStairs + "[facing=west,half=top]");
  setCell(14, seatY + 27, 13, woodStairs + "[facing=south,half=top]");
  setCell(14, seatY + 27, 15, woodStairs + "[facing=north,half=top]");

  // Mast Yardarm at y0 = 29
  for (let x = 10; x <= 18; x++) {
    if (x !== 14) {
      setCell(x, seatY + 29, 14, woodLog + "[axis=x]");
    }
  }

  // Rigging Chains
  setCell(10, seatY + 28, 14, "minecraft:chain");
  setCell(10, seatY + 27, 13, "minecraft:chain");
  setCell(10, seatY + 26, 12, "minecraft:chain");
  setCell(10, seatY + 25, 11, "minecraft:chain");

  setCell(18, seatY + 28, 14, "minecraft:chain");
  setCell(18, seatY + 27, 13, "minecraft:chain");
  setCell(18, seatY + 26, 12, "minecraft:chain");
  setCell(18, seatY + 25, 11, "minecraft:chain");

  // Jolly Roger Black Flag (Suspended from yardarm at z = 13, y0 = 26..29)
  for (let x = 11; x <= 17; x++) {
    for (let y0 = 26; y0 <= 29; y0++) {
      let wool = "minecraft:black_wool";

      // Skull & Crossbones motif
      if ((x === 13 || x === 14 || x === 15) && y0 === 28) wool = "minecraft:white_wool";
      if (x === 14 && y0 === 27) wool = "minecraft:white_wool";
      if ((x === 12 || x === 16) && y0 === 29) wool = "minecraft:white_wool";
      if ((x === 12 || x === 16) && y0 === 26) wool = "minecraft:white_wool";

      // Ragged distressed pirate cuts
      if (y0 === 26 && (x === 13 || x === 15)) continue;

      setCell(x, seatY + y0, 13, wool);
    }
  }

  // Atmospheric Lanterns & Iron Fixtures
  setCell(14, seatY + 8, 5, "minecraft:chain");
  setCell(14, seatY + 7, 5, "minecraft:lantern[hanging=true]");

  setCell(9, seatY + 25, 8, "minecraft:lantern[hanging=false]");
  setCell(19, seatY + 25, 8, "minecraft:lantern[hanging=false]");
  setCell(14, seatY + 30, 13, "minecraft:lantern[hanging=false]");

  setCell(14, seatY + 18, 14, "minecraft:chain");
  setCell(14, seatY + 17, 14, "minecraft:lantern[hanging=true]");
  setCell(14, seatY + 6, 14, "minecraft:chain");
  setCell(14, seatY + 5, 14, "minecraft:lantern[hanging=true]");

  // -------------------------------------------------------------
  // Phase 5: Complete Ground Conformance (Rule 6 & Rule 5)
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let lowestOccupiedY = -1;
      for (let y = 0; y < H; y++) {
        if (grid[x][y][z] !== null) {
          lowestOccupiedY = y;
          break;
        }
      }

      if (lowestOccupiedY !== -1) {
        const terrainH = api.heightAt(x, z);
        const targetGroundY = seatY + terrainH;

        // Where terrain falls away below structure, build foundations down
        if (targetGroundY < lowestOccupiedY) {
          const stopY = Math.max(0, targetGroundY);
          for (let y = lowestOccupiedY - 1; y >= stopY; y--) {
            const hash = Math.sin(x * 5.1 + y * 4.3 + z * 3.7) * 10000;
            const rnd = hash - Math.floor(hash);
            grid[x][y][z] = rnd < 0.6 ? stonePrimary : (rnd < 0.85 ? stoneAccent : scree);
          }
        }

        // Where terrain rises above seat plane, fill core so rock sits directly on hill
        if (targetGroundY > seatY) {
          for (let y = seatY; y <= Math.min(H - 1, targetGroundY); y++) {
            if (grid[x][y][z] === null) {
              grid[x][y][z] = stonePrimary;
            }
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // Phase 6: Commit Blocks to API
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "pirate_skull_rock",
    seatY: seatY,
    anchors: {
      front: [14, seatY + 1, 0],
      door: [14, seatY + 1, 4],
      lookout: [14, seatY + 28, 14]
    },
    interiors: [
      {
        min: [10, seatY + 1, 8],
        max: [18, seatY + 6, 20],
        kind: "vault"
      },
      {
        min: [9, seatY + 14, 8],
        max: [19, seatY + 18, 19],
        kind: "hall"
      }
    ]
  };
}

