export const envelope = [27, 48, 27];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 13;
  const cz = 13;
  const seatY = 6;

  // Grid buffer for safe in-bounds composition
  const grid = new Map();

  function setBlock(x, y, z, block) {
    x = Math.round(x);
    y = Math.round(y);
    z = Math.round(z);
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    grid.set(`${x},${y},${z}`, block);
  }

  function withState(blockStr, stateStr) {
    const base = blockStr.split("[")[0];
    return `${base}[${stateStr}]`;
  }

  // Palette resolution from world theme with crystalline unicorn sanctuary fallbacks
  const stone = api.theme.stone?.primary || "minecraft:smooth_quartz";
  const stoneBricks = api.theme.ground?.plinth || "minecraft:quartz_bricks";
  const stoneAccent = api.theme.stone?.accent || "minecraft:quartz_pillar";
  const stoneStairs = api.theme.stone?.stairs || "minecraft:quartz_stairs";
  const pavement = api.theme.ground?.pavement || "minecraft:smooth_quartz";

  // Arcane & Crystal Materials
  const quartz = "minecraft:smooth_quartz";
  const amethyst = "minecraft:amethyst_block";
  const buddingAmethyst = "minecraft:budding_amethyst";
  const tintedGlass = "minecraft:tinted_glass";
  const seaLantern = "minecraft:sea_lantern";
  const cryingObsidian = "minecraft:crying_obsidian";
  const gold = "minecraft:gold_block";
  const gildedBlackstone = "minecraft:gilded_blackstone";
  const amethystClusterUp = "minecraft:amethyst_cluster[facing=up]";

  // Geometric primitive helpers
  function fillEllipsoid(ex, ey, ez, rx, ry, rz, block) {
    const minX = Math.max(0, Math.floor(ex - rx));
    const maxX = Math.min(W - 1, Math.ceil(ex + rx));
    const minY = Math.max(0, Math.floor(ey - ry));
    const maxY = Math.min(H - 1, Math.ceil(ey + ry));
    const minZ = Math.max(0, Math.floor(ez - rz));
    const maxZ = Math.min(D - 1, Math.ceil(ez + rz));

    for (let x = minX; x <= maxX; x++) {
      const dx = (x - ex) / rx;
      for (let y = minY; y <= maxY; y++) {
        const dy = (y - ey) / ry;
        for (let z = minZ; z <= maxZ; z++) {
          const dz = (z - ez) / rz;
          if (dx * dx + dy * dy + dz * dz <= 1.0) {
            setBlock(x, y, z, block);
          }
        }
      }
    }
  }

  function fillCapsule(p1, p2, r1, r2, block) {
    const dist = Math.hypot(p2[0] - p1[0], p2[1] - p1[1], p2[2] - p1[2]);
    const steps = Math.max(1, Math.ceil(dist * 2.5));
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const x = p1[0] + (p2[0] - p1[0]) * t;
      const y = p1[1] + (p2[1] - p1[1]) * t;
      const z = p1[2] + (p2[2] - p1[2]) * t;
      const r = r1 + (r2 - r1) * t;
      fillEllipsoid(x, y, z, r, r, r, block);
    }
  }

  function evalPiecewise(pts, t) {
    t = Math.max(0, Math.min(1, t));
    const scaled = t * (pts.length - 1);
    const idx = Math.min(pts.length - 2, Math.floor(scaled));
    const frac = scaled - idx;
    const p0 = pts[idx];
    const p1 = pts[idx + 1];
    return [
      p0[0] + (p1[0] - p0[0]) * frac,
      p0[1] + (p1[1] - p0[1]) * frac,
      p0[2] + (p1[2] - p0[2]) * frac
    ];
  }

  function getStairFacing(dx, dz) {
    if (Math.abs(dx) > Math.abs(dz)) {
      return dx > 0 ? "facing=east,half=bottom" : "facing=west,half=bottom";
    } else {
      return dz > 0 ? "facing=south,half=bottom" : "facing=north,half=bottom";
    }
  }

  // --- 1. DAIS, PLINTH & GROUND CONFORMANCE ---
  const maxR = 11.5;
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const distSq = dx * dx + dz * dz;
      const octDist = Math.abs(dx) + Math.abs(dz);

      if (distSq <= maxR * maxR && octDist <= 16.5) {
        const gh = api.heightAt(x, z);
        const groundY = Math.max(0, Math.min(H - 1, seatY + gh));
        const minY = Math.min(seatY, groundY);
        const maxY = Math.max(seatY, groundY);

        // Foundation skirt extending down to the terrain
        for (let y = minY; y <= maxY; y++) {
          setBlock(x, y, z, stoneBricks);
        }

        const r = Math.sqrt(distSq);

        // Tier 1: Plinth Base (y = seatY = 6)
        if (r <= 11.2) {
          if (r > 10.2) {
            setBlock(x, seatY, z, withState(stoneStairs, getStairFacing(dx, dz)));
          } else {
            setBlock(x, seatY, z, stoneBricks);
          }
        }

        // Tier 2: Arcane Glyphs Ring (y = 7)
        if (r <= 10.0) {
          let b = pavement;
          if (r >= 6.8 && r <= 8.8) {
            const angle = Math.atan2(dz, dx);
            const starAngle = Math.round(angle / (Math.PI / 4)) * (Math.PI / 4);
            if (Math.abs(angle - starAngle) < 0.18 && Math.abs(r - 7.8) < 0.9) {
              b = seaLantern;
            } else {
              b = (Math.abs(dx * dz) % 2 === 0) ? cryingObsidian : amethyst;
            }
          }
          setBlock(x, seatY + 1, z, b);
        }

        // Tier 3: Inner Terrace (y = 8)
        if (r <= 8.5) {
          if (r > 7.6) {
            setBlock(x, seatY + 2, z, withState(stoneStairs, getStairFacing(dx, dz)));
          } else {
            setBlock(x, seatY + 2, z, pavement);
          }
        }

        // Tier 4: Pedestal Foundation (y = 9)
        if (r <= 6.8) {
          setBlock(x, seatY + 3, z, stoneBricks);
        }

        // Tier 5: Pedestal Platform (y = 10)
        if (r <= 5.2) {
          let b = pavement;
          if (Math.abs(dx) <= 1 || Math.abs(dz) <= 1) {
            b = amethyst;
          }
          setBlock(x, seatY + 4, z, b);
        }
      }
    }
  }

  // Grand North Stairs leading up to the dais
  for (let step = 0; step <= 4; step++) {
    const sy = seatY + step;
    const sz = cz - 11 + step * 1.2;
    for (let x = cx - 3; x <= cx + 3; x++) {
      for (let z = Math.floor(sz); z <= Math.floor(sz + 1.2); z++) {
        if (z >= 0 && z < D) {
          setBlock(x, sy, z, withState(stoneStairs, "facing=south,half=bottom"));
        }
      }
    }
  }

  // 4 Corner Crystal Beacon Spires on the Dais
  const spires = [[-8, -8], [8, -8], [-8, 8], [8, 8]];
  for (const [ox, oz] of spires) {
    const sx = cx + ox;
    const sz = cz + oz;
    for (let y = seatY + 1; y <= seatY + 5; y++) {
      setBlock(sx, y, sz, stoneAccent);
      setBlock(sx + 1, y, sz, stoneAccent);
      setBlock(sx, y, sz + 1, stoneAccent);
      setBlock(sx + 1, y, sz + 1, stoneAccent);
    }
    setBlock(sx, seatY + 6, sz, seaLantern);
    setBlock(sx + 1, seatY + 6, sz, seaLantern);
    setBlock(sx, seatY + 6, sz + 1, seaLantern);
    setBlock(sx + 1, seatY + 6, sz + 1, seaLantern);

    setBlock(sx, seatY + 7, sz, amethystClusterUp);
    setBlock(sx + 1, seatY + 7, sz + 1, amethystClusterUp);
  }

  // --- 2. CRYSTAL GEODE OUTCROP (Raised Front-Right Hoof) ---
  const geodeX = cx + 4;
  const geodeZ = cz - 4;
  for (let x = geodeX - 1; x <= geodeX + 1; x++) {
    for (let z = geodeZ - 1; z <= geodeZ + 1; z++) {
      for (let y = seatY + 4; y <= seatY + 6; y++) {
        setBlock(x, y, z, amethyst);
      }
      setBlock(x, seatY + 7, z, buddingAmethyst);
    }
  }
  setBlock(geodeX + 1, seatY + 8, geodeZ, amethystClusterUp);
  setBlock(geodeX - 1, seatY + 8, geodeZ + 1, amethystClusterUp);

  // --- 3. ALICORN LEGS & HOOVES ---
  function buildHoof(hx, hy, hz) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dz = -1; dz <= 1; dz++) {
        if (Math.abs(dx) + Math.abs(dz) <= 1) {
          setBlock(hx + dx, hy, hz + dz, gold);
          setBlock(hx + dx, hy + 1, hz + dz, gildedBlackstone);
        }
      }
    }
  }

  // Back Left Leg
  buildHoof(cx - 4, seatY + 4, cz + 4);
  fillCapsule([cx - 4, seatY + 5, cz + 4], [cx - 4, seatY + 8, cz + 4.5], 1.0, 1.0, quartz);
  fillCapsule([cx - 4, seatY + 8, cz + 4.5], [cx - 3.5, seatY + 12, cz + 3.5], 1.0, 1.4, quartz);

  // Back Right Leg
  buildHoof(cx + 4, seatY + 4, cz + 4);
  fillCapsule([cx + 4, seatY + 5, cz + 4], [cx + 4, seatY + 8, cz + 4.5], 1.0, 1.0, quartz);
  fillCapsule([cx + 4, seatY + 8, cz + 4.5], [cx + 3.5, seatY + 12, cz + 3.5], 1.0, 1.4, quartz);

  // Front Left Leg
  buildHoof(cx - 4, seatY + 4, cz - 3);
  fillCapsule([cx - 4, seatY + 5, cz - 3], [cx - 4, seatY + 9, cz - 2.8], 1.0, 1.0, quartz);
  fillCapsule([cx - 4, seatY + 9, cz - 2.8], [cx - 3.5, seatY + 13, cz - 1.5], 1.0, 1.4, quartz);

  // Front Right Leg (Resting proud on the Crystal Outcrop)
  buildHoof(cx + 4, seatY + 7, cz - 4);
  fillCapsule([cx + 4, seatY + 8, cz - 4], [cx + 4, seatY + 11, cz - 3.5], 1.0, 1.0, quartz);
  fillCapsule([cx + 4, seatY + 11, cz - 3.5], [cx + 3.5, seatY + 14, cz - 1.5], 1.0, 1.4, quartz);

  // --- 4. TORSO, BARREL & AEGIS CORE ---
  fillEllipsoid(cx, seatY + 13.5, cz - 1.5, 3.4, 3.2, 2.8, quartz);
  fillEllipsoid(cx, seatY + 13.5, cz + 3.5, 3.2, 2.8, 2.5, quartz);
  fillCapsule([cx, seatY + 13.5, cz + 3.5], [cx, seatY + 13.5, cz - 1.5], 2.8, 3.2, quartz);
  fillEllipsoid(cx, seatY + 15.0, cz - 1.5, 2.2, 2.5, 2.0, quartz);

  // Glowing "Heart of the Aegis" inside the chest
  setBlock(cx, seatY + 13, cz - 1, seaLantern);
  setBlock(cx, seatY + 14, cz - 1, seaLantern);
  setBlock(cx, seatY + 13, cz - 2, cryingObsidian);
  setBlock(cx, seatY + 14, cz - 2, tintedGlass);

  // --- 5. ARCHED NECK, HEAD, MUZZLE & EARS ---
  fillCapsule([cx, seatY + 14.0, cz - 1.5], [cx, seatY + 18.0, cz - 4.0], 2.5, 2.0, quartz);
  fillCapsule([cx, seatY + 18.0, cz - 4.0], [cx, seatY + 22.5, cz - 6.5], 2.0, 1.6, quartz);

  // Equine Head and Jaw
  fillEllipsoid(cx, seatY + 23.5, cz - 7.2, 1.8, 1.8, 1.8, quartz);
  fillEllipsoid(cx, seatY + 22.2, cz - 6.5, 2.0, 1.8, 1.6, quartz);
  fillCapsule([cx, seatY + 23.0, cz - 7.5], [cx, seatY + 21.5, cz - 10.0], 1.5, 1.1, quartz);

  // Radiant Crystal Eyes
  setBlock(cx - 1, seatY + 23, cz - 8, seaLantern);
  setBlock(cx - 2, seatY + 23, cz - 8, amethyst);
  setBlock(cx + 1, seatY + 23, cz - 8, seaLantern);
  setBlock(cx + 2, seatY + 23, cz - 8, amethyst);

  // Ears
  fillCapsule([cx - 1.3, seatY + 24.5, cz - 6.5], [cx - 1.6, seatY + 27.0, cz - 5.8], 0.6, 0.4, quartz);
  fillCapsule([cx + 1.3, seatY + 24.5, cz - 6.5], [cx + 1.6, seatY + 27.0, cz - 5.8], 0.6, 0.4, quartz);

  // --- 6. BILLOWING AMETHYST MANE ---
  const manePoints = [
    [cx, seatY + 25.5, cz - 7.0],
    [cx, seatY + 23.5, cz - 5.5],
    [cx, seatY + 20.5, cz - 4.0],
    [cx, seatY + 17.5, cz - 2.5],
    [cx, seatY + 15.0, cz - 1.0]
  ];
  for (let i = 0; i < manePoints.length; i++) {
    const p = manePoints[i];
    fillEllipsoid(p[0], p[1], p[2], 1.2, 1.2, 1.0, amethyst);
    const side = (i % 2 === 0) ? 1 : -1;
    fillEllipsoid(p[0] + side * 1.5, p[1] - 0.5, p[2] + 0.5, 0.9, 0.9, 0.9, tintedGlass);
    fillEllipsoid(p[0] - side * 1.2, p[1] - 0.7, p[2] + 0.8, 0.8, 0.8, 0.8, amethyst);
  }

  // --- 7. AMETHYST CRYSTAL SPIRE HORN ---
  const hornBase = [cx, seatY + 24.5, cz - 8.0];
  const hornTip = [cx, seatY + 34.0, cz - 12.0];
  const hornSteps = 24;
  for (let i = 0; i <= hornSteps; i++) {
    const t = i / hornSteps;
    const px = hornBase[0] + (hornTip[0] - hornBase[0]) * t;
    const py = hornBase[1] + (hornTip[1] - hornBase[1]) * t;
    const pz = hornBase[2] + (hornTip[2] - hornBase[2]) * t;
    const r = 1.4 * (1 - t * 0.85);

    let block = amethyst;
    if (t > 0.9) {
      block = amethystClusterUp;
    } else if (i % 4 === 0) {
      block = seaLantern;
    } else if (i % 2 === 0) {
      block = tintedGlass;
    }
    fillEllipsoid(px, py, pz, r, r, r, block);

    // Spiraling crystal facets along the horn
    const angle = t * Math.PI * 6;
    const spiralR = r + 0.4;
    const sx = px + Math.cos(angle) * spiralR;
    const sz = pz + Math.sin(angle) * spiralR;
    setBlock(sx, py, sz, (i % 2 === 0) ? amethyst : tintedGlass);
  }

  // --- 8. MAJESTIC AEGIS WINGS ---
  function buildWing(sign) {
    const spar = [
      [cx + sign * 3.0, seatY + 14.0, cz - 0.5],
      [cx + sign * 6.0, seatY + 18.0, cz + 0.5],
      [cx + sign * 8.5, seatY + 23.0, cz + 1.5],
      [cx + sign * 11.0, seatY + 28.5, cz + 2.5],
      [cx + sign * 12.0, seatY + 30.5, cz + 4.5]
    ];

    const trail = [
      [cx + sign * 3.5, seatY + 12.0, cz + 3.0],
      [cx + sign * 5.5, seatY + 15.0, cz + 5.0],
      [cx + sign * 8.0, seatY + 19.0, cz + 7.0],
      [cx + sign * 10.5, seatY + 23.5, cz + 8.5],
      [cx + sign * 12.0, seatY + 29.5, cz + 6.0]
    ];

    // Main leading spar
    for (let i = 0; i < spar.length - 1; i++) {
      const r1 = 1.3 - i * 0.15;
      const r2 = 1.3 - (i + 1) * 0.15;
      fillCapsule(spar[i], spar[i + 1], r1, r2, quartz);
    }

    // Feather vanes
    const N_U = 22;
    const N_V = 14;
    for (let iu = 0; iu <= N_U; iu++) {
      const u = iu / N_U;
      const sPos = evalPiecewise(spar, u);
      const tPos = evalPiecewise(trail, u);

      for (let iv = 0; iv <= N_V; iv++) {
        const v = iv / N_V;
        const px = sPos[0] + (tPos[0] - sPos[0]) * v;
        const py = sPos[1] + (tPos[1] - sPos[1]) * v;
        const pz = sPos[2] + (tPos[2] - sPos[2]) * v;

        const rad = Math.max(0.6, 1.2 * (1 - v));

        let mat = quartz;
        if (v > 0.85 || (u > 0.8 && v > 0.5)) {
          mat = (iv % 2 === 0) ? amethyst : tintedGlass;
        } else if (v > 0.65 && iu % 3 === 0) {
          mat = tintedGlass;
        }

        fillEllipsoid(px, py, pz, rad, rad, rad, mat);
      }
    }
  }

  buildWing(-1); // Left Wing
  buildWing(1);  // Right Wing

  // --- 9. FLOWING CRYSTAL TAIL ---
  const tailPoints = [
    [cx, seatY + 13.5, cz + 5.0],
    [cx, seatY + 10.5, cz + 6.5],
    [cx, seatY + 7.5, cz + 7.8],
    [cx, seatY + 5.0, cz + 9.0],
    [cx, seatY + 4.0, cz + 10.0]
  ];
  for (let i = 0; i < tailPoints.length - 1; i++) {
    const r1 = 1.0 + i * 0.3;
    const r2 = 1.0 + (i + 1) * 0.3;
    fillCapsule(tailPoints[i], tailPoints[i + 1], r1, r2, quartz);

    const mid = evalPiecewise(tailPoints, (i + 0.5) / (tailPoints.length - 1));
    fillEllipsoid(mid[0] + 0.8, mid[1], mid[2], r1 * 0.7, r1 * 0.7, r1 * 0.7, amethyst);
    fillEllipsoid(mid[0] - 0.8, mid[1], mid[2], r1 * 0.7, r1 * 0.7, r1 * 0.7, tintedGlass);
  }

  // --- 10. FLUSH BLOCKS TO WORLD ---
  for (const [key, block] of grid) {
    const [x, y, z] = key.split(",").map(Number);
    api.set(x, y, z, block);
  }

  return {
    name: "Unicorn Crystal Colossus",
    seatY: seatY,
    anchors: {
      front: [cx, seatY, 0]
    }
  };
}

