export const envelope = [11, 10, 11];

export default function build(api) {
  const { size } = api;
  const seatY = 3;
  const deckY = 4;
  const variant = api.instance.index % 6;

  // --- Safe Palette Extraction ---
  function getThemeBlock(family, role, fallback) {
    if (api.theme && api.theme[family] && api.theme[family][role]) {
      return api.theme[family][role];
    }
    return fallback;
  }

  function withState(blockStr, state) {
    if (!blockStr) return "minecraft:oak_planks";
    const bracketIndex = blockStr.indexOf('[');
    const baseName = bracketIndex !== -1 ? blockStr.slice(0, bracketIndex) : blockStr;
    return state ? `${baseName}[${state}]` : baseName;
  }

  const woodPlanks = getThemeBlock("wood", "planks", "minecraft:oak_planks");
  const woodLog = getThemeBlock("wood", "log", "minecraft:oak_log");
  const woodStripped = getThemeBlock("wood", "stripped", "minecraft:stripped_oak_log");
  const woodStairs = getThemeBlock("wood", "stairs", "minecraft:oak_stairs");
  const woodSlab = getThemeBlock("wood", "slab", "minecraft:oak_slab");
  const woodFence = getThemeBlock("wood", "fence", "minecraft:oak_fence");
  const woodTrapdoor = getThemeBlock("wood", "trapdoor", "minecraft:oak_trapdoor");

  const stonePrimary = getThemeBlock("stone", "primary", "minecraft:stone_bricks");
  const stoneAccent = getThemeBlock("stone", "accent", "minecraft:cobblestone");
  const stoneStairs = getThemeBlock("stone", "stairs", "minecraft:stone_brick_stairs");
  const stoneSlab = getThemeBlock("stone", "slab", "minecraft:stone_brick_slab");
  const stoneWall = getThemeBlock("stone", "wall", "minecraft:cobblestone_wall");

  const groundPlinth = getThemeBlock("ground", "plinth", stonePrimary);
  const groundRevetment = getThemeBlock("ground", "revetment", stoneAccent);
  const groundPavement = getThemeBlock("ground", "pavement", woodPlanks);

  // --- Safe Block Placement Wrapper ---
  function setBlock(x, y, z, block) {
    if (x < 0 || x >= size[0] || y < 0 || y >= size[1] || z < 0 || z >= size[2]) {
      return;
    }
    api.set(x, y, z, block);
  }

  // --- Footprint Geometry (Octagonal Bastion Redoubt) ---
  function isPlatform(x, z) {
    const dx = x - 5;
    const dz = z - 5;
    return Math.abs(dx) <= 4 && Math.abs(dz) <= 4 && (Math.abs(dx) + Math.abs(dz) <= 6);
  }

  function isPerimeter(x, z) {
    if (!isPlatform(x, z)) return false;
    return !isPlatform(x + 1, z) || !isPlatform(x - 1, z) ||
           !isPlatform(x, z + 1) || !isPlatform(x, z - 1);
  }

  // --- 1. Ground Conformity & Sub-Deck Foundation ---
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      if (!isPlatform(x, z)) continue;

      const h = api.heightAt(x, z);
      const terrainY = Math.round(seatY + h);
      const bottomY = Math.max(0, Math.min(seatY, terrainY));
      const topFoundationY = Math.max(seatY, terrainY);
      const perim = isPerimeter(x, z);

      // Build foundation from ground level up to seat plane
      for (let y = bottomY; y <= topFoundationY; y++) {
        if (perim) {
          if ((x + z) % 2 === 0) {
            setBlock(x, y, z, withState(woodLog, "axis=y"));
          } else {
            setBlock(x, y, z, groundRevetment);
          }
        } else {
          setBlock(x, y, z, (y === bottomY) ? groundPlinth : stonePrimary);
        }
      }

      // Solid Deck Floor
      if (perim && (z === 1 || z === 2)) {
        setBlock(x, deckY, z, withState(woodStripped, "axis=x"));
      } else if (x === 5) {
        setBlock(x, deckY, z, withState(woodStripped, "axis=z"));
      } else {
        setBlock(x, deckY, z, groundPavement);
      }
    }
  }

  // --- 2. Rear Access Stairs (South Side, z = 8..10) ---
  for (let x = 4; x <= 6; x++) {
    const h10 = api.heightAt(x, 10);
    const bottomY10 = Math.max(0, Math.min(2, Math.round(seatY + h10)));
    for (let y = bottomY10; y <= 1; y++) {
      setBlock(x, y, 10, groundRevetment);
    }
    setBlock(x, 2, 10, withState(woodStairs, "facing=south,half=bottom,shape=straight"));

    const h9 = api.heightAt(x, 9);
    const bottomY9 = Math.max(0, Math.min(3, Math.round(seatY + h9)));
    for (let y = bottomY9; y <= 2; y++) {
      setBlock(x, y, 9, groundRevetment);
    }
    setBlock(x, 3, 9, withState(woodStairs, "facing=south,half=bottom,shape=straight"));

    setBlock(x, deckY, 8, withState(woodStairs, "facing=south,half=bottom,shape=straight"));
  }

  // Stair Balustrades
  setBlock(3, 5, 8, woodFence);
  setBlock(7, 5, 8, woodFence);
  setBlock(3, 4, 9, woodFence);
  setBlock(7, 4, 9, woodFence);

  // --- 3. Fortified Palisade Mantlet & Parapet Walls ---
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      if (!isPerimeter(x, z)) continue;

      // Skip rear stair opening
      if (z >= 8 && x >= 4 && x <= 6) continue;

      // Front Mantlet facing North (-Z)
      if (z === 1) {
        if (x === 5) {
          // Central Gun Embrasure
          setBlock(x, 5, z, withState(woodSlab, "type=bottom"));
          setBlock(x, 7, z, withState(woodTrapdoor, "facing=north,half=top,open=true"));
        } else if (x === 4 || x === 6) {
          // Embrasure Cheeks
          setBlock(x, 5, z, withState(woodLog, "axis=y"));
          setBlock(x, 6, z, withState(woodLog, "axis=y"));
          setBlock(x, 7, z, withState(woodTrapdoor, "facing=north,half=top,open=true"));
          setBlock(x, 5, 0, withState(woodTrapdoor, "facing=north,half=bottom,open=false"));
          setBlock(x, 6, 0, withState(woodTrapdoor, "facing=north,half=top,open=false"));
        } else {
          // Mantlet Log Wall with Sharpened Merlons
          setBlock(x, 5, z, withState(woodLog, "axis=y"));
          setBlock(x, 6, z, withState(woodLog, "axis=y"));
          setBlock(x, 7, z, withState(woodStairs, "facing=north,half=bottom,shape=straight"));
          setBlock(x, 5, 0, withState(woodTrapdoor, "facing=north,half=bottom,open=false"));
        }
      } else if (z === 2 && (x === 2 || x === 8)) {
        // Northwest and Northeast Bastion Corner Bastions
        setBlock(x, 5, z, withState(woodLog, "axis=y"));
        setBlock(x, 6, z, withState(woodLog, "axis=y"));
        setBlock(x, 7, z, woodFence);
      } else if (x === 1 || x === 9) {
        // Flank Parapet Walls
        setBlock(x, 5, z, stonePrimary);
        if (z % 2 === 1) {
          setBlock(x, 6, z, stoneWall);
        } else {
          setBlock(x, 6, z, woodFence);
        }
      } else if (z >= 7) {
        // Rear Flank Low Walls
        setBlock(x, 5, z, stoneWall);
      }
    }
  }

  // --- 4. Heavy Cannon & Wooden Carriage (Centered at x = 5) ---
  // Carriage Wheels & Cheeks
  setBlock(4, 5, 4, withState(woodTrapdoor, "facing=west,half=bottom,open=false"));
  setBlock(6, 5, 4, withState(woodTrapdoor, "facing=east,half=bottom,open=false"));
  setBlock(4, 5, 5, withState(woodStairs, "facing=north,half=bottom,shape=straight"));
  setBlock(6, 5, 5, withState(woodStairs, "facing=north,half=bottom,shape=straight"));
  setBlock(5, 5, 5, withState(woodTrapdoor, "facing=north,half=bottom,open=false"));

  // Cannon Barrels by Variant
  if (variant === 0) {
    // Heavy Grand Bronze Culverin
    setBlock(5, 5, 5, "minecraft:raw_copper_block");
    setBlock(5, 5, 4, "minecraft:cut_copper");
    setBlock(5, 5, 3, "minecraft:exposed_cut_copper");
    setBlock(5, 5, 2, "minecraft:cut_copper");
    setBlock(5, 5, 1, "minecraft:lightning_rod[facing=north]");
  } else if (variant === 1) {
    // Forged Iron Siege Bombard
    setBlock(5, 5, 5, "minecraft:polished_basalt[axis=z]");
    setBlock(5, 5, 4, "minecraft:polished_blackstone");
    setBlock(5, 5, 3, "minecraft:polished_basalt[axis=z]");
    setBlock(5, 5, 2, "minecraft:dispenser[facing=north]");
    setBlock(5, 6, 4, withState(stoneSlab, "type=bottom"));
  } else if (variant === 2) {
    // Weathered Shore Demicanon (Battle-Damaged)
    setBlock(5, 5, 5, "minecraft:weathered_cut_copper");
    setBlock(5, 5, 4, "minecraft:weathered_cut_copper");
    setBlock(5, 5, 3, "minecraft:weathered_cut_copper");
    setBlock(5, 5, 2, "minecraft:dispenser[facing=north]");
    setBlock(5, 5, 1, "minecraft:lightning_rod[facing=north]");
  } else if (variant === 3) {
    // Snub-Nosed Carronade & Northwest Swivel Gun
    setBlock(5, 5, 5, "minecraft:dark_oak_stairs[facing=south,half=top]");
    setBlock(5, 5, 4, "minecraft:polished_blackstone");
    setBlock(5, 5, 3, "minecraft:cauldron");
    setBlock(5, 5, 2, "minecraft:dispenser[facing=north]");

    // Swivel gun on NW corner post
    setBlock(2, 6, 2, "minecraft:dispenser[facing=north]");
  } else if (variant === 4) {
    // Flagship Harbor Long-Gun
    setBlock(5, 5, 5, "minecraft:cut_copper");
    setBlock(5, 5, 4, "minecraft:raw_copper_block");
    setBlock(5, 5, 3, "minecraft:cut_copper");
    setBlock(5, 5, 2, "minecraft:cut_copper");
    setBlock(5, 5, 1, "minecraft:dispenser[facing=north]");
  } else {
    // High-Angle Strait Mortar
    setBlock(5, 5, 5, "minecraft:polished_blackstone_stairs[facing=north,half=bottom]");
    setBlock(5, 5, 4, "minecraft:polished_blackstone");
    setBlock(5, 6, 4, "minecraft:cauldron");
    setBlock(5, 6, 3, "minecraft:dispenser[facing=north]");
    setBlock(5, 5, 3, "minecraft:polished_blackstone_stairs[facing=south,half=bottom]");
  }

  // --- 5. Ammunition, Tools & Equipment (Instance Distinct) ---
  // Powder and shot on West flank (x = 2, 3)
  setBlock(2, 5, 5, "minecraft:coal_block");
  setBlock(3, 5, 5, "minecraft:coal_block");
  setBlock(2, 6, 5, "minecraft:wither_skeleton_skull[rotation=0]");
  setBlock(2, 5, 6, "minecraft:barrel[facing=up]");
  setBlock(3, 5, 6, "minecraft:tnt");

  // Crew equipment on East flank (x = 7, 8)
  setBlock(8, 5, 4, "minecraft:cauldron");
  setBlock(8, 5, 5, woodFence);
  setBlock(8, 6, 5, woodFence);
  setBlock(7, 5, 6, "minecraft:barrel[facing=north]");

  // --- 6. Superstructure Variations (Awnings, Signal Masts & Cranes) ---
  if (variant === 0) {
    // Tall Lookout Rigging Mast (Rear East)
    for (let y = 5; y <= 9; y++) {
      setBlock(8, y, 7, withState(woodLog, "axis=y"));
    }
    setBlock(7, 8, 7, woodFence);
    setBlock(9, 8, 7, woodFence);
    setBlock(7, 7, 7, "minecraft:lantern[hanging=true]");
    setBlock(8, 9, 7, "minecraft:wither_skeleton_skull[rotation=0]");
  } else if (variant === 1) {
    // 4-Post Protective Timber Canopy
    const posts = [[2, 4], [8, 4], [2, 7], [8, 7]];
    for (const [px, pz] of posts) {
      for (let y = 5; y <= 7; y++) {
        setBlock(px, y, pz, woodFence);
      }
    }
    for (let x = 2; x <= 8; x++) {
      for (let z = 4; z <= 7; z++) {
        if (x === 2 || x === 8 || z === 4 || z === 7) {
          setBlock(x, 8, z, withState(woodSlab, "type=bottom"));
        }
      }
    }
    setBlock(5, 7, 6, "minecraft:lantern[hanging=true]");
  } else if (variant === 2) {
    // Signal Brazier on Stone Pedestal
    setBlock(8, 5, 6, stonePrimary);
    setBlock(8, 6, 6, stoneWall);
    setBlock(8, 7, 6, "minecraft:campfire[facing=north,lit=true]");

    // Flagpole on West flank
    for (let y = 5; y <= 8; y++) {
      setBlock(2, y, 7, woodFence);
    }
    setBlock(2, 8, 7, "minecraft:wither_skeleton_skull[rotation=0]");
  } else if (variant === 3) {
    // Central Battle Ensign Pole
    for (let y = 5; y <= 9; y++) {
      setBlock(5, y, 7, woodFence);
    }
    setBlock(4, 8, 7, woodFence);
    setBlock(6, 8, 7, woodFence);
    setBlock(4, 7, 7, "minecraft:lantern[hanging=true]");
    setBlock(6, 7, 7, "minecraft:lantern[hanging=true]");
  } else if (variant === 4) {
    // Artillery Shell Hoist Crane
    for (let y = 5; y <= 8; y++) {
      setBlock(8, y, 6, withState(woodLog, "axis=y"));
    }
    setBlock(7, 8, 6, withState(woodLog, "axis=x"));
    setBlock(6, 8, 6, withState(woodLog, "axis=x"));
    setBlock(6, 7, 6, "minecraft:chain[axis=y]");
    setBlock(6, 6, 6, "minecraft:grindstone[face=ceiling,facing=north]");

    // West flag mast
    for (let y = 5; y <= 8; y++) {
      setBlock(2, y, 7, woodFence);
    }
    setBlock(2, 7, 7, "minecraft:lantern[hanging=true]");
  } else {
    // Fortified Merlon Bastion with West Lean-to Shelter
    for (let z = 5; z <= 7; z++) {
      setBlock(2, 7, z, withState(woodStairs, "facing=east,half=bottom,shape=straight"));
      setBlock(3, 7, z, withState(woodSlab, "type=top"));
    }
    setBlock(8, 5, 7, stonePrimary);
    setBlock(8, 6, 7, "minecraft:campfire[facing=north,lit=true]");
  }

  return {
    name: "Fortified Cannon Battery",
    seatY,
    anchors: {
      front: [5, deckY, 0],
      entrance: [5, deckY, 10]
    }
  };
}
